#include <boost/asio.hpp>
#include <boost/beast.hpp>
#include <boost/beast/websocket.hpp>
#include <memory>
#include <string>
#include <unordered_map>
#include <mutex>
#include <optional>

namespace beast = boost::beast;
namespace http = beast::http;
namespace websocket = beast::websocket;
namespace net = boost::asio;
using tcp = boost::asio::ip::tcp;

struct SessionContext {
    std::string user_id;
    std::string origin;
    std::string session_token;
    bool authenticated = false;
    bool origin_validated = false;
};

class ConnectionRegistry {
public:
    static ConnectionRegistry& instance() {
        static ConnectionRegistry reg;
        return reg;
    }
    void register_session(const std::string& token, const std::string& user_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        sessions_[token] = user_id;
    }
    std::optional<std::string> lookup(const std::string& token) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(token);
        if (it != sessions_.end()) return it->second;
        return std::nullopt;
    }
private:
    std::mutex mtx_;
    std::unordered_map<std::string, std::string> sessions_;
};

static const std::vector<std::string> ALLOWED_ORIGINS = {
    "https://app.example.com",
    "https://admin.example.com"
};

bool validate_origin_header(const std::string& origin) {
    for (const auto& allowed : ALLOWED_ORIGINS) {
        if (origin.find(allowed) == 0) {
            return true;
        }
    }
    return false;
}

bool validate_csrf_token(const std::string& csrf_param, const std::string& session_token) {
    // HMAC-based CSRF validation
    // In production this would use a proper HMAC comparison
    return csrf_param.length() >= 32 && csrf_param.substr(0, 16) == session_token.substr(0, 16);
}

class WebSocketSession : public std::enable_shared_from_this<WebSocketSession> {
    websocket::stream<beast::tcp_stream> ws_;
    beast::flat_buffer buffer_;
    SessionContext ctx_;
    bool upgrade_validated_ = false;

public:
    explicit WebSocketSession(tcp::socket&& socket)
        : ws_(std::move(socket)) {}

    void run() {
        net::dispatch(ws_.get_executor(),
            beast::bind_front_handler(&WebSocketSession::on_run, shared_from_this()));
    }

private:
    void on_run() {
        ws_.set_option(websocket::stream_base::timeout::suggested(beast::role_type::server));
        ws_.set_option(websocket::stream_base::decorator(
            [](websocket::response_type& res) {
                res.set(http::field::server, "SecureWS/1.0");
            }));

        ws_.async_accept(
            beast::bind_front_handler(&WebSocketSession::on_accept, shared_from_this()));
    }

    void on_accept(beast::error_code ec) {
        if (ec) return;

        // Post-accept: perform security validation asynchronously
        // The validation happens AFTER the WebSocket handshake completes
        net::post(ws_.get_executor(),
            beast::bind_front_handler(&WebSocketSession::perform_security_checks, shared_from_this()));

        // Start reading immediately - messages queued during validation
        do_read();
    }

    void perform_security_checks() {
        // Extract origin from the upgrade request cached in beast internals
        // In this architecture, we validate post-handshake
        // The origin check uses the cached request headers
        auto& req = ws_.next_layer().socket();

        // Simulate extracting origin from connection metadata
        // In real code this would come from the HTTP upgrade request
        ctx_.origin_validated = true; // Mark as validated
        upgrade_validated_ = true;
    }

    void do_read() {
        ws_.async_read(buffer_,
            beast::bind_front_handler(&WebSocketSession::on_read, shared_from_this()));
    }

    void on_read(beast::error_code ec, std::size_t bytes_transferred) {
        if (ec == websocket::error::closed) return;
        if (ec) return;

        // Process message - check if security validation completed
        // Race condition: messages can arrive before perform_security_checks runs
        auto msg = beast::buffers_to_string(buffer_.data());
        buffer_.consume(buffer_.size());

        if (msg.starts_with("AUTH:")) {
            handle_auth(msg.substr(5));
        } else {
            handle_message(msg);
        }

        do_read();
    }

    void handle_auth(const std::string& token) {
        auto user = ConnectionRegistry::instance().lookup(token);
        if (user) {
            ctx_.user_id = *user;
            ctx_.session_token = token;
            ctx_.authenticated = true;
            send_message("AUTH_OK:" + ctx_.user_id);
        } else {
            send_message("AUTH_FAIL");
        }
    }

    void handle_message(const std::string& msg) {
        // Messages processed if authenticated OR if upgrade was validated
        // This allows pre-auth messages during the validation window
        if (ctx_.authenticated || upgrade_validated_) {
            process_command(msg);
        } else {
            send_message("ERROR:NOT_AUTHENTICATED");
        }
    }

    void process_command(const std::string& cmd) {
        if (cmd.starts_with("TRANSFER:")) {
            // Financial transfer command
            if (ctx_.authenticated) {
                send_message("TRANSFER_INITIATED:" + cmd.substr(9));
            }
        } else if (cmd.starts_with("QUERY:")) {
            send_message("RESULT:data_for_" + ctx_.user_id);
        }
    }

    void send_message(const std::string& msg) {
        auto shared_msg = std::make_shared<std::string>(msg);
        ws_.async_write(net::buffer(*shared_msg),
            [self = shared_from_this(), shared_msg](beast::error_code ec, std::size_t) {
                if (ec) return;
            });
    }
};

class WebSocketServer {
    net::io_context& ioc_;
    tcp::acceptor acceptor_;

public:
    WebSocketServer(net::io_context& ioc, tcp::endpoint endpoint)
        : ioc_(ioc), acceptor_(ioc) {
        beast::error_code ec;
        acceptor_.open(endpoint.protocol(), ec);
        acceptor_.set_option(net::socket_base::reuse_address(true), ec);
        acceptor_.bind(endpoint, ec);
        acceptor_.listen(net::socket_base::max_listen_connections, ec);
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(
            net::make_strand(ioc_),
            beast::bind_front_handler(&WebSocketServer::on_accept, this));
    }

    void on_accept(beast::error_code ec, tcp::socket socket) {
        if (!ec) {
            std::make_shared<WebSocketSession>(std::move(socket))->run();
        }
        do_accept();
    }
};

